import{_ as a,o as s,c as n,a0 as o}from"./chunks/framework.CNDWyMYS.js";const h=JSON.parse('{"title":"Integrating distro modules with LuaRocks","description":"","frontmatter":{},"headers":[],"relativePath":"integrating_distro_modules_with_luarocks.md","filePath":"integrating_distro_modules_with_luarocks.md"}'),t={name:"integrating_distro_modules_with_luarocks.md"};function i(l,e,p,c,r,u){return s(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="integrating-distro-modules-with-luarocks" tabindex="-1">Integrating distro modules with LuaRocks <a class="header-anchor" href="#integrating-distro-modules-with-luarocks" aria-label="Permalink to &quot;Integrating distro modules with LuaRocks&quot;">​</a></h1><p>This is documentation on strategies to integrate OS-installed modules (e.g. packages such as <code>luafilesystem</code> and <code>lpeg</code> provided by Linux distros) with existing versions of LuaRocks.</p><p>This page will list two approaches: the minimal one, and a more complete one that extends the first one.</p><h2 id="assumptions" tabindex="-1">Assumptions <a class="header-anchor" href="#assumptions" aria-label="Permalink to &quot;Assumptions&quot;">​</a></h2><ul><li>The examples below use Lua 5.3 — just change &quot;5.3&quot; to &quot;5.1&quot; or &quot;5.2&quot; and the same applies.</li><li>Distro-installed modules live at standard Lua locations under <code>/usr</code>, such as <code>/usr/lib/lua/5.3/lfs.so</code></li></ul><h2 id="the-bare-minimum-approach" tabindex="-1">The bare minimum approach <a class="header-anchor" href="#the-bare-minimum-approach" aria-label="Permalink to &quot;The bare minimum approach&quot;">​</a></h2><p>This is the <em>minimum</em> that should be added to distro module packages so that they visible as dependencies by LuaRocks:</p><h3 id="the-main-manifest-file" tabindex="-1">The main manifest file <a class="header-anchor" href="#the-main-manifest-file" aria-label="Permalink to &quot;The main manifest file&quot;">​</a></h3><p>For LuaRocks to be able to find any OS-installed modules, there needs to be an index file called <code>manifest</code> at <code>/usr/lib/luarocks/rocks-5.3/</code>.</p><p>This file should be generated running:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>luarocks-admin make-manifest --local-tree --tree=/usr</span></span></code></pre></div><p>This should be run as a post-install action after installing any module via the distro. This file is the LuaRocks &quot;index&quot; and should be kept up-to-date or else LuaRocks doesn&#39;t know about the installed modules.</p><h3 id="rock-metadata-necessary-to-build-the-main-manifest" tabindex="-1">Rock metadata necessary to build the main manifest <a class="header-anchor" href="#rock-metadata-necessary-to-build-the-main-manifest" aria-label="Permalink to &quot;Rock metadata necessary to build the main manifest&quot;">​</a></h3><p>For the above command to work, there has to be a directory tree for each rock and version, containing, at the bare minimum, a <code>rock_manifest</code> file. The structure looks like this:</p><p><code>/usr/lib/luarocks/rocks-$LUA_VERSION/$ROCK_NAME/$ROCK_VERSION-$ROCK_REVISION/</code></p><ul><li><p>$LUA_VERSION with with a dot: &quot;5.3&quot;</p></li><li><p>$ROCK_NAME should match the name used in the luarocks.org repository — in other words, <code>luafilesystem</code> has to be called <code>luafilesystem</code>, not <code>lfs</code>. LuaRocks checks dependencies by rock name, not by individual module name.</p></li><li><p>$ROCK_VERSION usually matches upstream, so that&#39;s not an issue.</p></li><li><p>$ROCK_REVISION can always be 0 for our purposes here.</p></li></ul><p>Examples:</p><ul><li>/usr/lib/luarocks/rocks-5.3/lpeg/1.0.0-0/</li><li>/usr/lib/luarocks/rocks-5.3/luafilesystem/1.6.0-0/</li><li>/usr/lib/luarocks/rocks-5.3/lua-cjson/2.1.0-0/</li></ul><h3 id="the-rock-manifest-file" tabindex="-1">The rock_manifest file <a class="header-anchor" href="#the-rock-manifest-file" aria-label="Permalink to &quot;The rock_manifest file&quot;">​</a></h3><p>Inside the version directory for a rock there must be a <code>rock_manifest</code> file. The minimal contents of <code>rock_manifest</code> to make <code>luarocks-admin</code> not fail is simply:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rock_manifest </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {}</span></span></code></pre></div><p>This means that in the above examples, we&#39;d have several identical one-liner files:</p><ul><li>/usr/lib/luarocks/rocks-5.3/lpeg/1.0.0-0/rock_manifest</li><li>/usr/lib/luarocks/rocks-5.3/luafilesystem/1.6.0-0/rock_manifest</li><li>/usr/lib/luarocks/rocks-5.3/lua-cjson/2.1.0-0/rock_manifest</li></ul><h3 id="necessary-luarocks-configuration" tabindex="-1">Necessary LuaRocks configuration <a class="header-anchor" href="#necessary-luarocks-configuration" aria-label="Permalink to &quot;Necessary LuaRocks configuration&quot;">​</a></h3><p>With those empty manifests, the post-install operation mentioned above works and a later <code>luarocks install</code> will the existence of the &quot;rocks&quot; in /usr, given the following configuration in <code>/etc/luarocks/config-5.3.lua</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rocks_trees = {</span></span>
<span class="line"><span>   { name = &quot;user&quot;, root = home..&quot;/.luarocks&quot; },</span></span>
<span class="line"><span>   { name = &quot;distro-modules&quot;, root = &quot;/usr&quot; },</span></span>
<span class="line"><span>   { name = &quot;system&quot;, root = &quot;/usr/local&quot; },</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>deps_mode = &quot;all&quot;</span></span></code></pre></div><p>It&#39;s important that the &quot;system&quot; tree is the last entry: it is the one used for system-wide installation of rocks using LuaRocks (when <code>sudo luarocks</code> is used). The &quot;distro-modules&quot; tree should never be used directly by the user.</p><p>For more info on the deps_mode flag, see the <a href="./dependencies.html#dependency-modes">Dependency modes</a> documentation.</p><h3 id="caveats" tabindex="-1">Caveats <a class="header-anchor" href="#caveats" aria-label="Permalink to &quot;Caveats&quot;">​</a></h3><p><em>Error messages</em>: Running with such bare minimum setup will resolve dependencies, but running the post-install operation above will output error messages when running, such as...</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tree inconsistency detected: luafilesystem 1.6.0-0 has no rockspec. Could not load rockspec file /usr/lib/luarocks/rocks-5.3/luafilesystem/1.6.0-0/luafilesystem-1.6.0-0.rockspec (/usr/lib/luarocks/rocks-5.3/luafilesystem/1.6.0-0/luafilesystem-1.6.0-0.rockspec: No such file or directory)&quot;</span></span></code></pre></div><p>...for each entry under <code>/usr/lib/luarocks/rocks-5.3</code> (for our purposes, these can be simply ignored and silenced away with <code>&amp;&gt; /dev/null</code>).</p><p><em>Failed commands</em>: this minimal tree will work for solving dependencies, but not for much else. In particular, <code>luarocks list --tree=/usr</code> will work, but <code>luarocks show lpeg --tree=/user</code> will not, complaining that it can&#39;t find a rockspec.</p><h2 id="a-more-complete-approach" tabindex="-1">A more complete approach <a class="header-anchor" href="#a-more-complete-approach" aria-label="Permalink to &quot;A more complete approach&quot;">​</a></h2><p>A more complete approach to make commands such as <code>luarocks show</code> to work would entail two steps: adding proper contents to <code>rock_manifest</code> and including a rockspec file for each module.</p><h3 id="a-complete-rock-manifest" tabindex="-1">A complete rock_manifest <a class="header-anchor" href="#a-complete-rock-manifest" aria-label="Permalink to &quot;A complete rock_manifest&quot;">​</a></h3><p>A workable version of <code>rock_manifest</code> with contents would look like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rock_manifest = {</span></span>
<span class="line"><span>   lib = {</span></span>
<span class="line"><span>      [&quot;lpeg.so&quot;] = &quot;136a74c6e472c36a65449184e1820a31&quot;</span></span>
<span class="line"><span>   },</span></span>
<span class="line"><span>   [&quot;lpeg-1.0.0-0.rockspec&quot;] = &quot;4933a611af43404761002ee139c393e8&quot;,</span></span>
<span class="line"><span>   lua = {</span></span>
<span class="line"><span>      [&quot;re.lua&quot;] = &quot;5f09bb0129b09b6a8e8c1db1b206b1ca&quot;</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The entries under <code>lib</code> are the files installed by the package at <code>/usr/lib/5.3</code>. The entries under <code>lua</code> are the files installed by the package at <code>/usr/share/5.3</code>. The rockspec key is the rockspec file to be stored alongside the <code>rock_manifest</code> file. The values to these entries are MD5 sums to the files in question.</p><h3 id="including-a-rockspec-file" tabindex="-1">Including a rockspec file <a class="header-anchor" href="#including-a-rockspec-file" aria-label="Permalink to &quot;Including a rockspec file&quot;">​</a></h3><p>For <code>luarocks show</code> to display metadata properly, a rockspec file must exist. It should be named according to the pattern <code>$ROCK_NAME-$ROCK_VERSION-$ROCK_REVISION.rockspec</code> (in all lowercase). Continuing the examples above:</p><ul><li>/usr/lib/luarocks/rocks-5.3/lpeg/1.0.0-0/lpeg-1.0.0-0.rockspec</li><li>/usr/lib/luarocks/rocks-5.3/luafilesystem/1.6.0-0/luafilesystem-1.6.0-0.rockspec</li><li>/usr/lib/luarocks/rocks-5.3/lua-cjson/2.1.0-0/lua-cjson-2.1.0-0.rockspec</li></ul><p>For simplicity, I would recommend just copying over the appropriate rockspec file from <a href="https://luarocks.org" target="_blank" rel="noreferrer">luarocks.org</a> and bundling them in the package metadata. For completeness, this is how the one for LPeg 1.0 looks like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>package = &quot;LPeg&quot;</span></span>
<span class="line"><span>version = &quot;1.0.0-1&quot;</span></span>
<span class="line"><span>source = {</span></span>
<span class="line"><span>   url = &quot;https://www.inf.puc-rio.br/~roberto/lpeg/lpeg-1.0.0.tar.gz&quot;,</span></span>
<span class="line"><span>   md5 = &quot;0aec64ccd13996202ad0c099e2877ece&quot;,</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>description = {</span></span>
<span class="line"><span>   summary = &quot;Parsing Expression Grammars For Lua&quot;,</span></span>
<span class="line"><span>   detailed = [[</span></span>
<span class="line"><span>      LPeg is a new pattern-matching library for Lua, based on Parsing</span></span>
<span class="line"><span>      Expression Grammars (PEGs). The nice thing about PEGs is that it</span></span>
<span class="line"><span>      has a formal basis (instead of being an ad-hoc set of features),</span></span>
<span class="line"><span>      allows an efficient and simple implementation, and does most things</span></span>
<span class="line"><span>      we expect from a pattern-matching library (and more, as we can</span></span>
<span class="line"><span>      define entire grammars).</span></span>
<span class="line"><span>   ]],</span></span>
<span class="line"><span>   homepage = &quot;https://www.inf.puc-rio.br/~roberto/lpeg/lpeg.html&quot;,</span></span>
<span class="line"><span>   maintainer = &quot;Gary V. Vaughan &lt;gary@vaughan.pe&gt;&quot;,</span></span>
<span class="line"><span>   license = &quot;MIT/X11&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>dependencies = {</span></span>
<span class="line"><span>   &quot;lua &gt;= 5.1&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>build = {</span></span>
<span class="line"><span>   type = &quot;builtin&quot;,</span></span>
<span class="line"><span>   modules = {</span></span>
<span class="line"><span>      lpeg = {</span></span>
<span class="line"><span>         &quot;lpcap.c&quot;, &quot;lpcode.c&quot;, &quot;lpprint.c&quot;, &quot;lptree.c&quot;, &quot;lpvm.c&quot;</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      re = &quot;re.lua&quot;</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,44)])])}const m=a(t,[["render",i]]);export{h as __pageData,m as default};
